import{_ as n,l as o,o as e,c as s,v as t,p as l,x as r,d as h,i as E,S as m}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"偏度风险溢价","description":"","frontmatter":{"title":"偏度风险溢价","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/skew-risk-premium.md","filePath":"quant/skew-risk-premium.md","lastUpdated":1789023840000}'),d={name:"quant/skew-risk-premium.md"};function p(S,a,u,A,B,c){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="偏度风险溢价" tabindex="-1">偏度风险溢价 <a class="header-anchor" href="#偏度风险溢价" aria-label="Permalink to &quot;偏度风险溢价&quot;">​</a></h1><div class="epigraph"><p>风险中性偏度比物理偏度更负：市场为左尾支付的价格，超过随后实现的负偏本身；这一缺口是崩盘保险的价格，而不能从方差溢价里线性拆出来。</p><footer>—— Kozhan, Neuberger &amp; Schneider, The Skew Risk Premium in the Equity Index Market, Review of Financial Studies, 2013</footer></div><p>指数期权的虚值看跌贵，隐含分布左偏；历史收益的偏度也常为负，但通常没有隐含的那么负。偏度风险溢价（skew risk premium）把两个三阶矩对齐：\\(\\mathbb{Q}\\) 下的无模型偏度减 \\(\\mathbb{P}\\) 下预期已实现偏度。Roman Kozhan、Anthony Neuberger 与 Paul Schneider 证明，指数上这块溢价显著，且与方差风险溢价相关却不完全相同——微笑的斜度不是方差条带的线性变换。<a href="/quant/vol-skew">Skew 与微笑</a> 写形状；本篇写形状里被定价的那一项，以及它和<a href="/quant/variance-risk-premium">波动率风险溢价</a> 如何分担崩盘补偿。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>方差互换给二次变差定价，对正负跳动一视同仁（在扩散极限里）。投资者真正厌恶的是向下跳：组合保险、杠杆约束、习惯形成都对左尾更敏感。于是市场可以在方差上收费之外，再对三阶矩收费。若只看 VRP，会把「买保护」全部记在 \\(\\sigma^2\\) 上，高估方差因子、低估崩盘因子。问题是构造与 RV 同族的已实现偏度，以及与 VIX 同族的风险中性偏度，使二者之差有复制含义，而不是把 Black–Scholes 风险中性密度的偏度系数随便减一下历史偏度。</p><p>Bakshi、Kapadia 与 Madan（2003）给出用虚值期权拼出风险中性偏度、峰度的积分公式。Neuberger（2012）以及 KNS（2013）把已实现偏度定义成与期权复制一致的对象：用合约的日度盈亏或适当的收益函数，使样本均值能对上风险中性期望，差额才是溢价。用日收益的三阶样本矩去减隐含偏度，期限、跳的离散与年化都对不上，缺口里会混进定义误差。</p><h3 id="无模型隐含偏度与已实现偏度" tabindex="-1">无模型隐含偏度与已实现偏度 <a class="header-anchor" href="#无模型隐含偏度与已实现偏度" aria-label="Permalink to &quot;无模型隐含偏度与已实现偏度&quot;">​</a></h3><p>风险中性偏度来自虚值期权对执行价的积分，对左翼 \\(K\\) 的权重与方差条带的 \\(1/K^2\\) 不同，斜度（风险反转）对隐含偏度的贡献最大。已实现偏度要用与定价公式匹配的二次、三次变差估计量，而不是 \\(\\widehat{\\mathbb{E}}[(r-\\bar r)^3]/\\hat\\sigma^3\\) 的朴素样本偏度。KNS 强调：在他们的复制下，偏度互换的公平费率由期权给出，浮动腿由标的路径给出，溢价是固定腿减预期浮动腿。</p> \\[\\mathrm{SRP}_t=\\mathrm{Skew}_t^{\\mathbb{Q}}-\\mathbb{E}^{\\mathbb{P}}_t\\bigl[\\mathrm{Skew}_{t,t+h}^{\\mathrm{real}}\\bigr]. \\]<p>指数上 \\(\\mathrm{Skew}^{\\mathbb{Q}}\\) 更负，多方（买左尾、买负偏）平均付费。符号同样要先约定：有人把卖方收到的保险费记为正。比较 VRP 与 SRP 的相关时，两边须用同一期限、同一标的、同一套翼截断。</p><p><span class="marginnote">25-delta 风险反转是斜度的交易员坐标，不是 SRP。风险反转是两个隐含波动之差，SRP 是三阶矩的测度差。二者同向，但把 RR 减历史偏度写成 Kozhan–Neuberger–Schneider，口径错了。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>隐含腿。用与期限匹配的欧式切片，按 BKM 或 KNS 的权重积分虚值看涨看跌。翼不足时隐含偏度会被截断：缺更低的执行价会让左尾看起来不够肥，SRP 被低估。须报告最低 \\(K/F\\) 与是否用外推。物理腿。用高频收益构造已实现三次变差，或用 KNS 的互换浮动腿定义，再对未来 \\(h\\) 做条件期望。平静期已实现偏度噪声极大——三阶矩比二阶更难估——条件期望需要收缩，否则 SRP 序列会被一天的跳主导。</p><p>联合建模。方差与偏度溢价高度相关：崩盘时二者一起跳。KNS 的要点之一是，偏度溢价不能被方差溢价完全解释；控制 VRP 之后，斜度相关的收益仍然在。实务上可交易腿是风险反转、看跌价差、或偏度互换（OTC）。股票截面上，个股风险中性偏度（OTM 看跌贵）有时预测负收益，那是另一条特征溢价，不要与指数 SRP 混成同一个因子。</p><h3 id="与方差溢价、跳跃补偿的分工" tabindex="-1">与方差溢价、跳跃补偿的分工 <a class="header-anchor" href="#与方差溢价、跳跃补偿的分工" aria-label="Permalink to &quot;与方差溢价、跳跃补偿的分工&quot;">​</a></h3><p>扩散加杠杆相关（Heston）能生成负斜度，溢价可以主要表现为方差溢价：波动升的状态恰好是市场跌的状态。跳跃模型（Bates、Merton 跳）把崩盘写成强度与幅度，左尾保险费更多进入偏度与高阶。现实里两者都在：短到期斜度更陡，跳的份额更大；长到期斜度被随机波动与均值回复稀释。拆分可用：短端 SRP 对跳更敏感，长端 VRP 对连续方差更敏感；或用已实现跳检验把 RV 拆成连续与跳，再分别对隐含方差做溢价。不能指望一个数同时当 VIX 和当崩盘指数。</p>',16)),(e(),l(m,null,{default:r(()=>[E(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20SLICE%5B%22%E6%AC%A7%E5%BC%8F%E5%88%87%E7%89%87%22%5D%20--%3E%20QSK%5B%22Q%20%E5%81%8F%E5%BA%A6%EF%BC%9ABKM%20%2F%20KNS%20%E7%A7%AF%E5%88%86%22%5D%0A%20%20PATH%5B%22%E6%A0%87%E7%9A%84%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20RSK%5B%22%E5%B7%B2%E5%AE%9E%E7%8E%B0%E5%81%8F%E5%BA%A6%20%2F%20%E4%B8%89%E6%AC%A1%E5%8F%98%E5%B7%AE%22%5D%0A%20%20QSK%20--%3E%20SRP%5B%22%E5%81%8F%E5%BA%A6%E9%A3%8E%E9%99%A9%E6%BA%A2%E4%BB%B7%22%5D%0A%20%20RSK%20--%3E%20SRP%0A%20%20VRP%5B%22%E6%96%B9%E5%B7%AE%E9%A3%8E%E9%99%A9%E6%BA%A2%E4%BB%B7%22%5D%20--%3E%20JOINT%5B%22%E8%81%94%E5%90%88%EF%BC%9A%E5%B4%A9%E7%9B%98%E7%8A%B6%E6%80%81%22%5D%0A%20%20SRP%20--%3E%20JOINT%0A%20%20JOINT%20--%3E%20RR%5B%22%E9%A3%8E%E9%99%A9%E5%8F%8D%E8%BD%AC%20%2F%20%E7%9C%8B%E8%B7%8C%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20JOINT%20--%3E%20VS%5B%22%E6%96%B9%E5%B7%AE%E4%BA%92%E6%8D%A2%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>均衡里，边际效用在崩盘状态最高，左尾的状态价格密度相对物理密度更肥，隐含偏度更负。这与<a href="/quant/macro-factor-set">宏观因子</a> 的增长坏状态是同一类故事，但频率是日度尾部而不是季度 GDP。中介与需求：基金持续买入指数看跌，做市商收负跳暴露，隐含斜度被买出来，溢价里有「保险需求压力」，不完全是消费风险。1987 年之后斜度成为常态，需求通道很难再当成短暂摩擦。</p><p>行为通道：投资者高估崩盘概率，隐含左尾过肥。区分风险与错误信念，要看随后已实现左尾是否匹配隐含；长期看，实现偏度没有隐含那么负，溢价持续存在，更像价格而非纯预测偏差——除非信念错误本身长期不修正。对交易而言，两种解释的回撤相同：卖斜度的人在下一次崩盘赔钱。</p><h3 id="个股、信用与外汇" tabindex="-1">个股、信用与外汇 <a class="header-anchor" href="#个股、信用与外汇" aria-label="Permalink to &quot;个股、信用与外汇&quot;">​</a></h3><p>个股斜度还含借券与破产跳，SRP 与指数不可比；空头拥挤的名字看跌更贵，特征里混进融资。信用的负偏来自违约，用股票期权的 SRP 去解释 CDS 是跨市场投影，须走潜空间或复制组合，不能直接减。外汇更常出现对称微笑，偏度溢价的符号随货币对的利率差与避险地位变，不是指数那条「永远更负」的经验规则。把指数 SRP 当全球尾部因子可以，当作所有资产的偏度定价定律不行。</p><p><span class="marginnote">卖出虚值看跌吃到的平均收益，混合了方差溢价、偏度溢价和 Delta 残留。不把标的对冲干净、不把方差暴露剥离，就不能把这笔 PnL 标成 SRP。KNS 的对象是矩的测度差，不是某一笔看跌的历史夏普。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>三阶矩估计在短窗口上不稳定，SRP 作为择时信号的换手与噪声都大于 VRP。翼流动性在压力期先消失，需要 SRP 的时候恰好不能调仓。离散执行价、美式提前行使（个股、ETF）破坏欧式积分公式，指数欧式（SPX）是干净的实验室，其他市场要折损。</p><p>不要用微笑斜度的历史均值当风险价格，那是 \\(\\mathbb{Q}\\) 的形状，还没减 \\(\\mathbb{P}\\)。不要在股票五因子上加一个「风险反转收益」就宣布截面闭合：指数期权组合与股票排序组合的投资者不同，漏因子问题要用跨资产面板处理。也不要把本篇与 vol-skew 篇的动力学模型对立起来：Heston 与跳模型生成形状，SRP 问形状里有多少是价格；两者叠在同一张切片上。</p><p><span class="marginnote">真实出处：Kozhan, Neuberger &amp; Schneider, <em>The Skew Risk Premium in the Equity Index Market</em>, Review of Financial Studies, 2013；风险中性矩见 Bakshi, Kapadia &amp; Madan, Review of Financial Studies, 2003；已实现偏度见 Neuberger, Journal of Finance, 2012。不要把 25-delta 风险反转标成 2013 年论文的偏度互换定义。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>偏度风险溢价是风险中性三阶矩与物理预期已实现偏度之差，度量左尾保险的价格。</li><li>构造须与期权复制一致（BKM / KNS），不能用朴素样本偏度减 ATM 斜度。</li><li>与 VRP 相关但不相同：方差对正负对称，偏度针对崩盘；短端更偏跳。</li><li>可交易近似是风险反转与看跌价差，容量与翼流动性在压力期最差。</li><li>出处：Kozhan, Neuberger &amp; Schneider, Review of Financial Studies, 2013。</li></ul>',12))])}const R=n(d,[["render",p]]);export{b as __pageData,R as default};
